    [6, 0, 7]
]

# Let me check if there's a simple pattern extraction per 3x3 block
# Background is 5, so let's see which non-5 values exist in each block

grid_color_counts = {}
for r in range(9):
    for c in range(9):
        color = input_demo[r][c]
        if color != 5:
            block_r, block_c = r // 3, c // 3
            key = (block_r, block_c)
            if key not in grid_color_counts:
                grid_color_counts[key] = {}
            for pc in grid_color_counts[key]:
                grid_color_counts[key][pc] = 0
