                for cc in range(3):
                    color2 = input_demo[r + rr][c + cc]
                    if color2 != 5 and color2 in {'0', '1', '6', '7'}:
                        grid_color_counts[key][color2] = grid_color_counts[key].get(color2, 0) + 1

